      ]
    },
    {
      "title": "GaGNN",
      "link": "https://doi.org/10.1016/j.ins.2024.120623",
      "contributions": [
        "Motivates supplementing sparse histories with individual and group transition relationships."
      ],
      "limitations": [
        "Observed transitions establish predictive association rather than equipment compatibility or product complementarity."
      ]
    },
    {
      "title": "R2NS",
      "link": "https://renzhaochun.github.io/assets/pdf/WWW_2026_Camera_Ready.pdf",
      "contributions": [
        "Motivates uniform warm-up before progressively harder negative sampling."
      ],
      "limitations": [
        "Hard candidates can be unobserved positives; this motivates keeping the initial proposed experiment uniform."
      ]
    }
  ]
